// FUNCTION: BFME2 0x006BD650 size=39 name=?calcDistSquared@@YAMABVCoord3D@@0@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=B hypothesis:Z

static Real calcDotProduct(const Coord3D &a, const Coord3D &b)
{
	return a.x*b.x + a.y*b.y + a.z*b.z;
}

static Real calcDistSquared(const Coord3D &a, const Coord3D &b)
{
	Real dx = a.x - b.x;
	Real dy = a.y - b.y;
	Real dz = a.z - b.z;
	return dx*dx + dy*dy + dz*dz;
}

// FUNCTION: BFME2 0x006BD680 size=248 name=?calcPointToLineDistSquared@@YAMABVCoord3D@@00@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=B hypothesis:Z

static Real calcPointToLineDistSquared(const Coord3D &pt, const Coord3D &lineStart, const Coord3D &lineEnd)
{
	Coord3D line, lineToPt, closest;

	line.x = lineEnd.x - lineStart.x;
	line.y = lineEnd.y - lineStart.y;
	line.z = lineEnd.z - lineStart.z;

	lineToPt.x = pt.x - lineStart.x;
	lineToPt.y = pt.y - lineStart.y;
	lineToPt.z = pt.z - lineStart.z;

	Real dot = calcDotProduct(lineToPt, line);
	if (dot <= 0.0f)
	{
		// angle is obtuse
		return calcDistSquared(pt, lineStart);
	}

	Real lineLenSqr = calcDistSquared(lineStart, lineEnd);
	if (lineLenSqr <= dot)
	{
		return calcDistSquared(pt, lineEnd);
	}

	Real tmp = dot / lineLenSqr;

	closest.x = lineStart.x + tmp * line.x;
	closest.y = lineStart.y + tmp * line.y;
	closest.z = lineStart.z + tmp * line.z;

	return calcDistSquared(pt, closest);
}

// FUNCTION: BFME2 0x006BD780 size=59 name=?isIntersectedByLineSegment@GeometryInfo@@QBE_NABVCoord3D@@00@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=B hypothesis:Z

Bool GeometryInfo::isIntersectedByLineSegment(const Coord3D &loc, const Coord3D &from, const Coord3D &to) const
{
	/// @todo srj -- treats everything as a sphere for now. fix.
	Real boundingSphereRadius = m_minorRadius;
	Real distSquared = calcPointToLineDistSquared(loc, from, to);
	return distSquared <= boundingSphereRadius * boundingSphereRadius;
}

// FUNCTION: BFME2 0x006BD7C0 size=101 name=?getMaxHeightAbovePosition@GeometryInfo@@QBEMXZ evidence=N:ledger tier=A

Real GeometryInfo::getMaxHeightAbovePosition() const
{
	Real best = 0.0f;
	for (_STL::vector<GeometryShape>::const_iterator shape = m_shapes.begin(); shape != m_shapes.end(); ++shape)
	{
		if (!shape->m_flag)
			continue;

		Real height = 0.0f;
		switch (shape->m_type)
		{
			case GEOMETRY_SPHERE:
				height = shape->m_majorRadius;
				break;

			case GEOMETRY_BOX:
			case GEOMETRY_CYLINDER:
				height = shape->m_height;
				break;
		}

		height += shape->m_offsetZ;
		const Real &larger = (height > best) ? height : best;
		best = larger;
	}

	return best;
}

