// FUNCTION: BFME2 0x006BE4C0 size=159 name=?calcPitches@GeometryInfo@@QBEXABVCoord3D@@ABV1@0AAM2@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A

void GeometryInfo::calcPitches(const Coord3D &thisPos, const GeometryInfo &that, const Coord3D &thatPos, Real &minPitch, Real &maxPitch) const
{
	Coord3DBase center = m_center;
	Coord3D thisCenter;
	thisCenter.x = center.x + thisPos.x;
	thisCenter.y = center.y + thisPos.y;
	thisCenter.z = center.z + thisPos.z;

	Real dx = thatPos.x - thisCenter.x;
	Real dy = thatPos.y - thisCenter.y;
	Real dxy = sqrt(dx * dx + dy * dy);
	Real dz;

	dz = (thatPos.z + that.getMaxHeightAbovePosition()) - thisCenter.z;
	maxPitch = atan2(dz, dxy);

	dz = (thatPos.z - that.getMaxHeightBelowPosition()) - thisCenter.z;
	minPitch = atan2(dz, dxy);
}

